            // Set up step indicator
            setupStepIndicator();

            // Create initial diagram
            createInitialDiagram();

            // Set up event listeners
            setupEventListeners();

            // Expose demo API to window
            window.AIVA_DEMO = {
                reset: () => resetDemo(),
                next: () => advanceStep(),
                togglePlay: () => togglePlayback(),
                getState: () => getDemoState()
            };

            // Initialize to step 0
            resetDemo();
        }

        // Create initial diagram
        function createInitialDiagram() {
            // Clear existing content
            elements.diagram.innerHTML = '';

            // Create SVG container
            const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
            svg.className = "svg-diagram";
            svg.setAttribute("viewBox", "0 0 1200 400");
            svg.setAttribute("preserveAspectRatio", "xMidYMid meet");

            // Add user character
            const user = createCharacter(demo.characters[0], "user-circle", "User");
            svg.appendChild(user);

            // Add console element (as a simple box)
            const consoleBox = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            consoleBox.setAttribute("x", demo.characters[1].pos.x - 25);
            consoleBox.setAttribute("y", demo.characters[1].pos.y - 30);
            consoleBox.setAttribute("width", demo.characters[1].size * 2);
            consoleBox.setAttribute("height", demo.characters[1].size * 1.5);
            consoleBox.setAttribute("rx", "5");
            consoleBox.setAttribute("fill", "#ecf0f1");
            consoleBox.setAttribute("stroke", "#95a5a6");
            consoleBox.setAttribute("stroke-width", "1");
            svg.appendChild(consoleBox);

            // Add user bubble
            if (demo.characters[0].bubble) {
                addChatBubble(
                    svg,
                    demo.characters[0].bubble.pos.x - 80,
                    demo.characters[0].bubble.pos.y,
                    demo.characters[0].bubble.direction,
                    demo.characters[0].bubble.content,
                    "user-bubble"
